fn cid_from_opaque_ref(value: &str, prefix: &str) -> anyhow::Result<Cid> {
    let digest = value
        .strip_prefix(prefix)
        .filter(|digest| {
            digest.len() == 64
                && digest
                    .bytes()
                    .all(|byte| byte.is_ascii_hexdigit() && !byte.is_ascii_uppercase())
        })
        .ok_or_else(|| anyhow::anyhow!("Agent task runtime reference is invalid"))?;
    Ok(Cid {
        algo: HashAlgo::Blake3,
        digest: digest.to_string(),
    })
}

